package dev.zomboid.mts;
import java.util.*;
public final class VehicleInteraction {
 static String p="minecrafttransportsimulator.";
 static Object client(){return R.call(R.type("net.minecraft.client.Minecraft"),"getInstance");}
 static Object player(){return R.call(R.get(R.type(p+"mcinterface.InterfaceManager"),"clientInterface"),"getClientPlayer");}
 static Object point(Object v){return R.make(p+"baseclasses.Point3D",R.num(R.get(v,"x")),R.num(R.get(v,"y")),R.num(R.get(v,"z")));}
 static double distance(Object a,Object b){double d=0;for(String k:List.of("x","y","z")){double x=R.num(R.get(a,k))-R.num(R.get(b,k));d+=x*x;}return Math.sqrt(d);}
 public static boolean reachable(double distance){return distance<=5.0;}
 public static Object pick(){Object mc=client(),wrapper=player();if(wrapper==null||R.get(mc,"screen")!=null||R.get(mc,"level")==null||R.call(wrapper,"getEntityRiding")!=null)return null;Object eye=R.call(wrapper,"getEyePosition"),start,end;if(Mechanics.iso()){Object[] ray=(Object[])R.call(R.type("dev.zomboid.isotacz.CursorTarget"),"ray",mc);start=point(ray[0]);end=point(ray[1]);}else{start=R.call(eye,"copy");end=R.call(R.call(wrapper,"getLineOfSight",5d),"add",start);}Object world=R.call(wrapper,"getWorld"),result=R.call(world,"getMultipartEntityIntersect",start,end);if(Mechanics.iso())result=VehiclePicker.choose(world,eye,start,end,result);if(result==null||!reachable(distance(eye,R.get(result,"position"))))return null;Object pos=R.get(result,"position"),a=R.make("net.minecraft.world.phys.Vec3",R.num(R.get(eye,"x")),R.num(R.get(eye,"y")),R.num(R.get(eye,"z"))),b=R.make("net.minecraft.world.phys.Vec3",R.num(R.get(pos,"x")),R.num(R.get(pos,"y")),R.num(R.get(pos,"z")));Object context=R.make("net.minecraft.world.level.ClipContext",a,b,R.get(R.type("net.minecraft.world.level.ClipContext$Block"),"COLLIDER"),R.get(R.type("net.minecraft.world.level.ClipContext$Fluid"),"NONE"),R.get(mc,"player"));Object blocked=R.call(R.get(mc,"level"),"clip",context);if(R.call(blocked,"getType").toString().equals("BLOCK")&&distance(a,R.call(blocked,"getLocation"))<distance(a,b)-.1)return null;return result;}
 public static String[] describe(Object entity){String name=entity.getClass().getSimpleName();if(name.equals("PartSeat"))return new String[]{"Asiento",R.yes(R.get(R.get(entity,"placementDefinition"),"isController"))?"Subir y conducir":"Subir como pasajero"};if(name.equals("PartEngine"))return new String[]{"Motor","Mano vacia: revisar 1.5 s / Mecanica | Kit: reparar"};Object definition=R.get(entity,"definition");if("zomboid_trunk".equals(R.get(definition,"systemName")))return new String[]{"Maletera","Abrir almacenamiento: 54 espacios"};if(name.equals("PartInteractable"))return new String[]{"Almacenamiento del vehiculo","Abrir / interactuar"};return new String[]{"Vehiculo","Interactuar con puerta o pieza | Kit: reparar carroceria"};}
 public static String[] describeTarget(Object result){Object entity=R.get(result,"entity"),box=R.get(result,"box"),definition=R.get(box,"definition");if(definition!=null&&R.get(definition,"action")!=null){String variable=Objects.toString(R.get(R.get(definition,"action"),"variable"),"");if(variable.contains("hood"))return new String[]{"Motor / capo","Mano vacia: revisar 1.5 s / Mecanica"};if(variable.contains("trunk"))return new String[]{"Maletera","Abrir / cerrar"};if(variable.contains("door"))return new String[]{"Puerta del vehiculo","Abrir / cerrar"};}return describe(entity);}
 public static boolean click(){if(!Mechanics.iso())return false;Object result=pick();if(result==null)return false;Object wrapper=player(),packet=R.make(p+"packets.instances.PacketEntityInteract",R.get(result,"entity"),wrapper,R.get(result,"box"),false,true);Object packets=R.get(R.type(p+"mcinterface.InterfaceManager"),"packetInterface");R.call(packets,"sendToServer",packet);R.call(packets,"sendToServer",R.make(p+"packets.instances.PacketEntityInteract",R.get(result,"entity"),wrapper,R.get(result,"box"),false,false));return true;}
 public static void hint(Object graphics){Object mc=client();if(R.get(mc,"screen")!=null||R.yes(R.get(R.get(mc,"options"),"hideGui")))return;Object target=pick();if(target==null)return;String[] desc=describeTarget(target);Object key=R.call(R.call(R.get(R.get(mc,"options"),"keyUse"),"getTranslatedKeyMessage"),"getString"),font=R.get(mc,"font");String title=desc[0]+" ["+key+"]",detail=desc[1];int width=Math.max(((Number)R.call(font,"width",title)).intValue(),((Number)R.call(font,"width",detail)).intValue())+16,x=(((Number)R.call(graphics,"guiWidth")).intValue()-width)/2,y=48;R.call(graphics,"fill",x,y,x+width,y+32,0xB0202420);R.call(graphics,"drawString",font,title,x+8,y+5,0xFFFFDD55,true);R.call(graphics,"drawString",font,detail,x+8,y+18,0xFFE0E0E0,true);}
}
